def transform(grid):
    h, w = len(grid), len(grid[0])

    # Divider color is the color forming complete separator rows and columns.
    candidates = {}
    for r in range(h):
        if len(set(grid[r])) == 1:
            c = grid[r][0]
            candidates[c] = candidates.get(c, 0) + 1
    for c in range(w):
        vals = {grid[r][c] for r in range(h)}
        if len(vals) == 1:
            color = next(iter(vals))
            candidates[color] = candidates.get(color, 0) + 1
    divider = max(candidates, key=candidates.get)

    sep_rows = [r for r in range(h) if all(x == divider for x in grid[r])]
    sep_cols = [c for c in range(w) if all(grid[r][c] == divider for r in range(h))]

    row_edges = [-1] + sep_rows + [h]
    col_edges = [-1] + sep_cols + [w]
    row_blocks = [(row_edges[i] + 1, row_edges[i + 1])
                  for i in range(len(row_edges) - 1)]
    col_blocks = [(col_edges[i] + 1, col_edges[i + 1])
                  for i in range(len(col_edges) - 1)]

    colors = {}
    for row in grid:
        for value in row:
            if value != divider:
                colors[value] = colors.get(value, 0) + 1
    background = max(colors, key=colors.get)

    out = [[background for _ in col_blocks] for _ in row_blocks]
    for i, (r0, r1) in enumerate(row_blocks):
        for j, (c0, c1) in enumerate(col_blocks):
            count = sum(grid[r][c] != background
                        for r in range(r0, r1) for c in range(c0, c1))
            if count >= 2:
                out[i][j] = 1
    return out
